import {assetCategories,assetCategory,selectAssets} from './asset-model.mjs';
import {reportHtml} from '/precheck/export.mjs';
import {projectTypes,projectStages,projectSummary,selectProjects} from './project-model.mjs';
import {recentAssets,researchStage,stages} from './overview-model.mjs';
import {mountTool,toolConfigs} from './tools.mjs';
import {repository} from '/precheck/store.mjs';
import {esc,icon,empty,formatDate,download} from './ui.mjs';
import {keys,read,list,write,projects,preferences,profile,saveProject} from './state.mjs';
const $=s=>document.querySelector(s);
const categories=[['writing','AI 写作','pen',['writing','topic','proposal','summary','course','journal']],['literature','文献与研读','book',['search','reading','summary','translation']],['revision','修改与润色','pen',['review','rewrite','reduce']],['detection','论文检测','shield',['check','aigc']],['ppt','PPT 创作','chart',['ppt']],['research','科研工具','chart',['research']],['format','格式排版','file',['format']],['more','更多工具','grid',['resume','journal','translation']]];
const legacy={rewrite:'revision',reduce:'revision',check:'detection',aigc:'detection'};
let reports=[],reportError=false;
let homeAssetFilter='all';
let projectView=preferences().projectView==='list'?'list':'cards',projectSort=['activity','created','name'].includes(preferences().projectSort)?preferences().projectSort:'activity';
let assets=[],activeProjectFilter='all',assetFilter='all',assetQuery='',assetProject='all',assetSort='updated',projectQuery='';
const dialogId='workspace-dialog';let returnFocus=null;
function modal(title,html){if(!$('#workspace-dialog').open)returnFocus=document.activeElement;$('#workspace-dialog-title').textContent=title;$('#workspace-dialog-body').innerHTML=html;$( '#'+dialogId).showModal();}
function notify(message){$('#hub-toast').textContent=message;$('#hub-toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#hub-toast').classList.remove('visible'),3500);}
function guard(action){try{action();}catch{notify('本地存储失败，请先导出备份并检查浏览器空间。');}}
const projectOf=id=>projects().find(p=>p.id===id);
function refreshAssets(){assets=[...list(keys.drafts).map(d=>({id:String(d.id),type:'draft',title:d.title||'未命名成果',kind:d.stage==='draft'?'论文草稿':d.tool&&d.tool!=='writing'?toolConfigs[d.tool]?.[0]||'创作模板':'论文大纲',tool:d.tool||'writing',projectId:d.projectId||'',degree:d.degree||'',stamp:Date.parse(d.updatedAt)||Number(d.id)||0,date:d.date||'本地保存',url:'#draft/'+encodeURIComponent(d.id),data:d})),...reports.map(r=>({id:r.id,type:'report',title:r.title||'查重报告',kind:'查重报告',tool:'check',projectId:r.projectId||'',degree:r.degree||'',stamp:Date.parse(r.createdAt)||0,date:formatDate(r.createdAt),url:'/precheck/#/report/'+encodeURIComponent(r.id),data:r}))].sort((a,b)=>b.stamp-a.stamp);}
function avatar(){return `<span class="hub-avatar">${esc(Array.from(profile().name||'研究者')[0])}</span>`;}
function applyPreferences(){const p=preferences();document.body.classList.toggle('hub-compact',p.density==='compact');document.body.classList.toggle('hub-large-text',p.fontSize==='large');}
function shell(){const nav=(href,name,ico)=>`<a class="nav-link" href="${href}">${icon(ico,19)}<span>${name}</span></a>`;$('#app').innerHTML=`<aside class="sidebar hub-sidebar"><a class="brand" href="/"><span class="brand-symbol">P</span><span>PaperKnow<small>让研究更清晰</small></span></a><nav aria-label="工作台导航"><span class="nav-caption">工作空间</span>${nav('#home','工作台首页','grid')}${nav('#projects','我的项目','folder')}${nav('#assets','我的成果','file')}${nav('#tasks','任务中心','clock')}<span class="nav-caption">论文与科研</span>${categories.map(([key,name,ico])=>nav('#category/'+key,name,ico)).join('')}<span class="nav-caption">个人与服务</span>${nav('#membership','会员与用量','diamond')}${nav('#settings','设置中心','settings')}${nav('#help','帮助与反馈','help')}</nav><div class="hub-sidebar-profile"><button class="hub-profile-trigger" data-account-menu>${avatar()}<span><b class="hub-profile-name">${esc(profile().name)}</b><small>本地体验空间</small></span><span>⌄</span></button></div></aside><button class="hub-mobile-backdrop" id="sidebar-backdrop" aria-label="关闭导航菜单" tabindex="-1"></button><div class="workspace hub-workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn sidebar-toggle" id="menu-toggle" aria-label="切换菜单">${icon('menu')}</button><strong>工作台 / 概览</strong></div><div class="hub-top-actions"><form id="global-search-form"><label class="hub-search">${icon('search',16)}<input id="global-search" aria-label="搜索项目与成果" placeholder="搜索项目、成果与工具" maxlength="100"></label></form><a class="hub-toolbar" href="#tasks">${icon('clock',17)}<span>任务</span></a><button class="icon-btn" id="notification-button" aria-label="查看成果动态">${icon('bell',19)}</button><a class="hub-toolbar" href="#help">${icon('help',18)}<span>帮助</span></a><button class="hub-top-profile" data-account-menu aria-label="打开账户菜单">${avatar()}<span class="hub-profile-name">${esc(profile().name)}</span>⌄</button></div></header><main class="page dashboard hub-page"></main></div><div id="account-menu" class="hub-account-menu" hidden><a href="#account">账户中心</a><a href="#membership">会员与用量</a><a href="#orders">订单记录</a><a href="#settings">设置中心</a><a href="/">返回官网</a></div><dialog id="workspace-dialog" aria-labelledby="workspace-dialog-title"><header><h2 id="workspace-dialog-title"></h2><button class="icon-btn" id="workspace-dialog-close" aria-label="关闭窗口">${icon('close')}</button></header><div id="workspace-dialog-body"></div></dialog><div id="hub-toast" role="status" aria-live="polite"></div>`;
$('#menu-toggle').addEventListener('click',()=>$('.sidebar').classList.toggle('mobile-open'));$('#sidebar-backdrop').addEventListener('click',()=>$('.sidebar').classList.remove('mobile-open'));$('#workspace-dialog-close').addEventListener('click',()=>$('#'+dialogId).close());$('#'+dialogId).addEventListener('close',()=>returnFocus?.focus());$('#'+dialogId).addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))e.currentTarget.close();});
$('#global-search-form').addEventListener('submit',e=>{e.preventDefault();const q=$('#global-search').value.trim();if(q)location.hash='search/'+encodeURIComponent(q);});$('#notification-button').addEventListener('click',()=>{refreshAssets();modal('成果动态',`<p class="hub-intro">以下来自当前浏览器的实际保存记录，不代表在线通知。</p>${assets.slice(0,5).map(assetRow).join('')||empty('暂无保存的成果。','#category/writing')}`);});applyPreferences();}
const badge=(text,kind='blue')=>`<span class="hub-badge ${kind}">${text}</span>`;
const heading=(title,desc,actions='')=>`<div class="hub-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="hub-heading-actions">${actions}</div></div>`;
function assetRow(a){const linked=projectOf(a.projectId);return `<div class="hub-asset-row"><span class="hub-row-icon ${a.type==='report'?'mint':''}">${icon(a.type==='report'?'search':'file')}</span><div class="hub-row-copy"><b>${esc(a.title)}</b><p>${esc(a.kind)} · ${esc(linked?.name||'未归入项目')} · ${esc(a.date)}</p></div>${badge(a.type==='report'?'本地报告':a.data.stage==='draft'?'草稿':'可编辑',a.type==='report'?'mint':'blue')}<a class="hub-row-action" href="${esc(a.url)}">${a.type==='report'?'查看报告':'继续编辑'} ${icon('arrow',14)}</a></div>`;}
function projectRow(p){const related=assets.filter(a=>a.projectId===p.id);return `<div class="hub-project-row"><span class="hub-row-icon">${icon('folder')}</span><div class="hub-row-copy"><b>${esc(p.name)}</b><p>${esc(p.degree)} · ${esc(p.major||'学科待填写')} · ${related.length} 份成果 · ${formatDate(p.updatedAt)}</p></div>${badge(p.status==='archived'?'已归档':'进行中',p.status==='archived'?'gray':'blue')}<a class="hub-row-action" href="#project/${esc(p.id)}">继续查看 ${icon('arrow',14)}</a></div>`;}
function allTasks(){const reportTasks=reports.map(r=>({id:'report-'+r.id,title:r.title,kind:'本地文本比对',status:'completed',createdAt:r.createdAt,url:'/precheck/#/report/'+r.id}));return [...list(keys.tasks),...reportTasks].sort((a,b)=>(Date.parse(b.createdAt)||0)-(Date.parse(a.createdAt)||0));}
function taskRow(t){return `<div class="hub-task-row"><span class="hub-task-dot"></span><div class="hub-row-copy"><b>${esc(t.kind||t.title)}</b><p>${esc(t.title)} · ${formatDate(t.createdAt)}</p>${t.url?`<a href="${esc(t.url)}">查看成果 →</a>`:''}</div>${badge(t.status==='completed'?'已完成':'本地记录','mint')}</div>`;}
const quickTools=[['writing','AI 写作','从思路搭建框架','file','blue'],['check','论文查重','核对片段与来源','search','mint'],['rewrite','降重复率','整理修改思路','pen','blue'],['reduce','降 AI 率','完善表达与证据','shield','violet'],['reading','文献研读','阅读笔记与整理','book','mint'],['ppt','答辩 PPT','组织研究展示','chart','amber']];
function toolHref(id){return id==='check'?'/precheck/':'#tool/'+id;}
function newTask(){modal('新建任务',`<p class="hub-intro">选择你要完成的工作，无需先创建项目。当前在线 AI 服务尚未接入。</p><div class="hub-task-picker">${quickTools.map(([id,name,desc,ico,color])=>`<a href="${toolHref(id)}"><span class="hub-row-icon ${color}">${icon(ico,24)}</span><div><b>${name}</b><p>${desc}</p></div>${icon('arrow',16)}</a>`).join('')}</div><div class="hub-picker-footer"><span>需要长期整理研究内容？</span><button class="text-btn" data-new-project>创建研究项目 →</button></div>`);}
function uploadTask(){modal('上传论文后，你想做什么？',`<p class="hub-intro">先选择用途，再进入对应页面上传。文件仅在当前浏览器处理。</p><div class="hub-upload-options"><a href="/precheck/"><span class="hub-row-icon mint">${icon('search')}</span><div><b>论文查重</b><p>解析正文，与你提供的本地材料比对</p></div>${icon('arrow',16)}</a><a href="#tool/writing"><span class="hub-row-icon">${icon('file')}</span><div><b>作为写作参考材料</b><p>支持 DOCX / PDF / TXT 本地解析与核对</p></div>${icon('arrow',16)}</a></div><p class="hub-footnote">修改与排版目前支持粘贴文字和流程模板，暂不支持上传后自动处理。</p>`);}
function continueResearch(){const a=assets.find(a=>!projectOf(a.projectId)||projectOf(a.projectId).status!=='archived');if(!a)return `<section class="card hub-card hub-continue"><div class="hub-card-heading"><h2>继续研究</h2><a href="#projects">查看项目 ${icon('arrow',14)}</a></div><div class="hub-first-task">${icon('file',30)}<h3>从你的第一份研究内容开始</h3><p>创建任务后，保存的成果会出现在这里。</p><button class="btn primary" data-new-task>开始第一个任务</button></div></section>`;
const p=projectOf(a.projectId),stage=researchStage(a);return `<section class="card hub-card hub-continue"><div class="hub-card-heading"><h2>继续研究</h2><a href="#projects">查看项目 ${icon('arrow',14)}</a></div><div class="hub-resume-row"><span class="hub-row-icon">${icon(a.type==='report'?'search':'file',26)}</span><div class="hub-row-copy"><b>${esc(a.title)}</b><p>${esc(p?[p.degree,p.major].filter(Boolean).join(' · '):a.degree||'独立任务')} · ${esc(a.kind)} · ${formatDate(a.stamp)}</p></div>${badge(a.type==='report'?'报告已生成':a.data.stage==='draft'?'草稿已保存':'成果已保存','mint')}<a class="btn primary" href="${esc(a.url)}">${a.type==='report'?'查看报告':'继续编辑'}</a></div>${stage?`<div class="hub-research-stages" aria-label="当前内容对应的研究阶段">${stages.map(([id,label])=>`<span class="${id===stage?'current':''}" ${id===stage?'aria-current="step"':''}><i>${id===stage?'<span></span>':''}</i>${label}</span>`).join('')}</div><p class="hub-stage-note">高亮表示当前成果类型，不代表其他阶段已完成。</p>`:''}</section>`;}
function homeResults(){const rows=recentAssets(assets,homeAssetFilter).slice(0,3);return `<div class="hub-card-heading"><h2>最近成果</h2><a href="#assets">查看全部 ${icon('arrow',14)}</a></div><div class="hub-home-tabs" role="tablist" aria-label="最近成果分类">${[['all','全部'],['writing','写作'],['detection','检测'],['presentation','演示']].map(([id,label])=>`<button role="tab" aria-selected="${id===homeAssetFilter}" data-home-filter="${id}" class="${id===homeAssetFilter?'active':''}">${label}</button>`).join('')}</div><div role="tabpanel">${rows.map(assetRow).join('')||empty('此分类暂无保存的成果。',homeAssetFilter==='detection'?'/precheck/':homeAssetFilter==='presentation'?'#tool/ppt':'#category/writing','开始任务')}</div><p class="hub-footnote">相同内容合并展示；所有保存记录仍可在“我的成果”中查看。</p>`;}
function overview(){$('.dashboard').innerHTML=`${heading('今天，让研究再进一步','从一个想法开始，也可以继续上次的研究。',`<button class="btn secondary" data-upload-task>${icon('upload',17)}上传论文</button><button class="btn primary" data-new-task>${icon('plus',17)}新建任务</button>`)}<div class="hub-quick-grid">${quickTools.map(([id,name,desc,ico,color])=>`<a class="hub-quick" href="${toolHref(id)}"><span class="hub-row-icon ${color}">${icon(ico,24)}</span><div><h3>${name}</h3><p>${desc}</p></div></a>`).join('')}</div><div class="hub-overview-grid"><div>${continueResearch()}<section class="card hub-card hub-results" id="home-results">${homeResults()}</section><a class="hub-data-note" href="#settings/privacy">${icon('shield',25)}<div><b>论文与成果，由你掌握</b><p>当前内容保存在本地，请及时导出重要文件。</p></div><span>数据与隐私 →</span></a></div><div class="hub-overview-side"><section class="card hub-card hub-current-task"><div class="hub-card-heading"><h2>当前任务</h2><a href="#tasks">查看全部 ${icon('arrow',14)}</a></div><div class="hub-task-empty">${icon('clock',36)}<h3>暂无正在处理的任务</h3><p>在线任务服务尚未接入</p><a href="#tasks">查看本地记录 ${icon('arrow',14)}</a></div></section><section class="card hub-card hub-usage"><div class="hub-card-heading"><h2>用量与权益</h2>${badge('本地体验')}</div><p class="hub-description">正式账户与计费服务尚未接入</p><div class="hub-service-lines"><div>${icon('file',18)}本地编辑与保存 ${badge('可用','mint')}</div><div>${icon('search',18)}文档解析 ${badge('可用','mint')}</div><div>${icon('grid',18)}在线 AI 服务 ${badge('待接入','gray')}</div></div><a class="btn secondary" href="#membership">查看服务说明</a></section><section class="card hub-card hub-side-help"><h2>使用帮助</h2><a href="/precheck/#/help">${icon('book',19)}查重范围说明 ${icon('arrow',14)}</a><a href="#settings/privacy">${icon('help',19)}文件与数据保存 ${icon('arrow',14)}</a></section></div></div>`;}
function projectForm(id){const p=projectOf(id),pref=preferences();modal(p?'编辑项目':'新建研究项目',`<form id="project-form" class="hub-form"><label for="project-name">项目名称</label><input id="project-name" required minlength="2" maxlength="120" value="${esc(p?.name||'')}" placeholder="例如：人工智能辅助课堂学习反馈研究"><div class="hub-form-row"><div><label for="project-degree">学段 / 身份</label><select id="project-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===(p?.degree||pref.degree)?'selected':''}>${d}</option>`).join('')}</select></div><div><label for="project-major">学科专业</label><input id="project-major" maxlength="100" value="${esc(p?.major||pref.major)}" placeholder="例如：教育学"></div></div><div class="hub-form-row"><div><label for="project-type">项目类型</label><select id="project-type"><option value="">未分类研究</option>${projectTypes.map(t=>`<option ${p?.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="project-stage">当前阶段</label><select id="project-stage"><option value="">尚未设置</option>${projectStages.map(([key,label])=>`<option value="${key}" ${p?.stage===key?'selected':''}>${label}</option>`).join('')}</select></div></div><label for="project-description">研究说明（可选）</label><textarea id="project-description" rows="4" maxlength="2000" placeholder="记录研究目标与当前阶段…">${esc(p?.description||'')}</textarea><p class="hub-intro">项目和关联关系只保存在当前浏览器，不会自动上传。</p><p id="project-error" role="alert"></p><button class="btn primary" type="submit">${p?'保存项目':'创建项目'}</button></form>`);$('#project-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#project-name').value.trim();if(name.length<2){$('#project-error').textContent='项目名称至少填写 2 个字。';return;}try{const item=saveProject({name,type:$('#project-type').value,stage:$('#project-stage').value,degree:$('#project-degree').value,major:$('#project-major').value.trim(),description:$('#project-description').value.trim()},id);$('#'+dialogId).close();location.hash='project/'+item.id;if(id)render();}catch{$('#project-error').textContent='无法保存，请检查浏览器存储空间。';}});}
function projectStageMarkup(p){return `<div class="project-stage-heading"><b>当前阶段</b><button class="text-btn" data-stage-project="${esc(p.id)}">手动设置 ${icon('pen',14)}</button></div><div class="hub-research-stages project-stages" aria-label="手动设置的研究阶段">${projectStages.map(([id,label])=>`<span class="${p.stage===id?'current':''}" ${p.stage===id?'aria-current="step"':''}><i>${p.stage===id?'<span></span>':''}</i>${label}</span>`).join('')}</div>${!p.stage?'<p class="hub-stage-note">尚未设置阶段，请根据实际研究进展选择。</p>':''}`;}
function projectMenu(p){return `<details class="project-menu"><summary aria-label="${esc(p.name)}的更多操作">···</summary><div><button data-edit-project="${esc(p.id)}">编辑项目</button><button data-stage-project="${esc(p.id)}">设置阶段</button><button data-link-project="${esc(p.id)}">关联已有成果</button><button data-archive-project="${esc(p.id)}">${p.status==='archived'?'恢复项目':'归档项目'}</button></div></details>`;}
function projectCard(p){const info=projectSummary(p,assets),archived=p.status==='archived',chips=Object.entries(info.counts);return `<article class="project-card ${archived?'archived':''}"><div class="project-card-header"><span class="hub-row-icon">${icon('folder',28)}</span><div class="hub-row-copy"><div class="project-tags">${badge(esc(p.type||'未分类研究'))}${badge(archived?'已归档':'进行中',archived?'gray':'mint')}${projectView==='list'?badge(projectStages.find(([id])=>id===p.stage)?.[1]||'阶段未设置','gray'):''}</div><h2><a href="#project/${esc(p.id)}">${esc(p.name)}</a></h2><p>${esc(p.degree)} · ${esc(p.major||'学科待填写')}</p></div>${projectMenu(p)}</div>${!archived&&projectView==='cards'?`<p class="project-description">${esc(p.description||'记录研究目标，让下一步更清晰。')}</p>${projectStageMarkup(p)}<h3 class="project-assets-title">项目成果</h3>`:''}<div class="project-asset-chips">${chips.map(([label,count])=>`<span>${icon(label==='报告'?'chart':'file',15)}${esc(label)} <b>${count}</b></span>`).join('')||'<span class="project-no-assets">暂无关联成果</span>'}</div><p class="project-last-activity">${icon('clock',15)}${info.latest?`最近保存：${esc(info.latest.title)} · ${formatDate(info.latest.stamp)}`:`项目更新：${formatDate(p.updatedAt)}`}</p><div class="project-card-actions">${!archived?(info.latest?`<a class="btn primary" href="${esc(info.latest.url)}">${info.latest.type==='report'?'查看报告':'继续编辑'}</a>`:`<a class="btn secondary" href="#tool/writing?project=${esc(p.id)}">创建论文大纲</a>`):''}<a class="project-enter" href="#project/${esc(p.id)}">进入项目 ${icon('arrow',15)}</a></div></article>`;}
function projectRows(){const ps=selectProjects(projects(),assets,{status:activeProjectFilter,query:projectQuery,sort:projectSort});$('#project-rows').className='project-grid '+(projectView==='list'?'project-list':'');$('#project-rows').innerHTML=ps.map(projectCard).join('')||`<div class="project-empty">${icon('folder',38)}<h2>${projects().length?'没有匹配的项目':'创建你的第一个研究项目'}</h2><p>${projects().length?'试试其他关键词，或重置筛选。':'将研究说明、写作成果和检测报告整理在一起。'}</p><button class="btn primary" ${projects().length?'data-reset-projects':'data-new-project'}>${projects().length?'重置筛选':'新建项目'}</button></div>`;}
function renderProjects(){const ps=projects(),archived=ps.filter(p=>p.status==='archived').length;$('.dashboard').innerHTML=`${heading('我的项目','把论文、材料与成果，组织成清晰的研究进程。',`<button class="btn primary" data-new-project>${icon('plus',17)}新建项目</button>`)}<section class="project-toolbar"><div class="hub-tabs">${[['all','全部',ps.length],['active','进行中',ps.length-archived],['archived','已归档',archived]].map(([id,name,count])=>`<button data-project-filter="${id}" class="${id===activeProjectFilter?'active':''}" aria-pressed="${id===activeProjectFilter}">${name} <span>${count}</span></button>`).join('')}</div><div class="project-toolbar-right"><label class="project-search">${icon('search',16)}<input id="project-query" aria-label="搜索项目名称或研究方向" placeholder="搜索项目名称或研究方向" value="${esc(projectQuery)}"></label><select id="project-sort" aria-label="项目排序">${[['activity','最近活动'],['created','创建时间'],['name','项目名称']].map(([id,label])=>`<option value="${id}" ${projectSort===id?'selected':''}>${label}</option>`).join('')}</select><div class="project-view-toggle" aria-label="项目视图"><button data-project-view="cards" aria-label="卡片视图" aria-pressed="${projectView==='cards'}" class="${projectView==='cards'?'active':''}">${icon('grid',18)}</button><button data-project-view="list" aria-label="列表视图" aria-pressed="${projectView==='list'}" class="${projectView==='list'?'active':''}">${icon('menu',18)}</button></div></div></section><div id="project-rows"></div><div class="project-backup"><span class="hub-row-icon">${icon('shield',28)}</span><div><b>本地保存，记得备份</b><p>当前项目与成果保存在此浏览器，更换设备不会自动同步。</p></div><button class="btn secondary" data-workspace-backup>导出工作空间备份</button></div><p class="project-purpose">${icon('book',19)}项目用于长期组织研究；单次写作或查重，可直接在工作台新建任务。<a href="#home">工作台 ${icon('arrow',14)}</a></p>`;projectRows();$('#project-query').addEventListener('input',e=>{projectQuery=e.target.value;projectRows();});$('#project-sort').addEventListener('change',e=>{projectSort=e.target.value;guard(()=>write(keys.preferences,{...preferences(),projectSort}));projectRows();});}
function stageForm(id){const p=projectOf(id);if(!p)return;modal('设置研究阶段',`<form class="hub-form" id="project-stage-form"><p class="hub-intro">${esc(p.name)}：根据实际研究进展选择，不会自动标记其他阶段完成。</p><label for="project-stage-select">当前阶段</label><select id="project-stage-select"><option value="">尚未设置</option>${projectStages.map(([key,label])=>`<option value="${key}" ${key===p.stage?'selected':''}>${label}</option>`).join('')}</select><button class="btn primary" type="submit">保存阶段</button></form>`);$('#project-stage-form').addEventListener('submit',e=>{e.preventDefault();guard(()=>{saveProject({stage:$('#project-stage-select').value},id);$('#'+dialogId).close();render();notify('研究阶段已保存。');});});}
function exportWorkspace(){const backup={format:'paperknow-workspace-backup',version:1,exportedAt:new Date().toISOString(),projects:projects(),drafts:list(keys.drafts),reports,tasks:list(keys.tasks),profile:profile(),preferences:preferences()};download('PaperKnow-工作空间备份.json',JSON.stringify(backup,null,2),'application/json');notify('已发起备份下载，请确认浏览器已保存文件。');}
function projectDetail(id){const p=projectOf(id);if(!p){$('.dashboard').innerHTML=heading('项目不存在','可能在其他浏览器中创建，或当前存储中没有此项目。')+empty('返回项目列表查看。','#projects');return;}const related=assets.filter(a=>a.projectId===id);$('.dashboard').innerHTML=`${heading(esc(p.name),`${esc(p.degree)} · ${esc(p.major||'学科待填写')} · ${p.status==='archived'?'已归档':'进行中'}`,`<button class="btn secondary" data-edit-project="${esc(id)}">编辑项目</button><button class="btn secondary" data-archive-project="${esc(id)}">${p.status==='archived'?'恢复项目':'归档项目'}</button>`)}<div class="hub-project-actions"><a class="btn primary" href="#tool/writing?project=${encodeURIComponent(id)}">创建论文大纲</a><a class="btn secondary" href="/precheck/">上传论文查重</a><button class="btn secondary" data-link-project="${esc(id)}">关联已有成果</button></div><section class="card hub-card">${projectStageMarkup(p)}<h2 style="margin-top:24px">研究说明</h2><p class="hub-description">${esc(p.description||'还没有研究说明，点击编辑项目补充。')}</p><p class="hub-footnote">项目创建于 ${formatDate(p.createdAt)} · 归档只改变项目状态，不删除关联成果。</p></section><section class="card hub-card"><div class="hub-card-heading"><h2>项目成果</h2>${badge(related.length+' 份')}</div>${related.map(assetRow).join('')||empty('暂未关联成果，可创建大纲或关联已有记录。')}</section>`;}
function linkProject(id){modal('关联已有成果',`<p class="hub-intro">将当前浏览器中的成果归入此项目，不会改变正文或报告内容。</p><div class="hub-link-list">${assets.map(a=>`<div><span><b>${esc(a.title)}</b><small>${esc(a.kind)} · ${esc(projectOf(a.projectId)?.name||'未归入项目')}</small></span><button class="btn secondary" data-bind-asset="${esc(a.type+':'+a.id)}" data-target-project="${esc(id)}" ${a.projectId===id?'disabled':''}>${a.projectId===id?'已关联':'关联'}</button></div>`).join('')||empty('还没有成果。','#category/writing')}</div>`);}
async function bindAsset(type,id,projectId){try{if(type==='draft'){const rows=list(keys.drafts);write(keys.drafts,rows.map(d=>String(d.id)===id?{...d,projectId}:d));}else{const r=reports.find(r=>r.id===id);if(!r)throw Error();const updated={...r,projectId};await repository.save('reports',updated);reports=reports.map(r=>r.id===id?updated:r);}refreshAssets();notify(projectId?'成果已关联项目。':'已解除项目关联。');render();if($('#'+dialogId).open)linkProject(projectId);}catch{notify('关联失败，原成果仍保留。');}}
function assetToken(a){return a.type+':'+a.id;}
function assetByToken(token){return assets.find(a=>assetToken(a)===token);}
function assetDate(a){return a.stamp?new Date(a.stamp).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'时间未记录';}
function assetDescription(a){if(a.type==='report')return a.data.sources?.some(s=>s.kind==='demo')?'含演示材料 · 本地比对报告':'本地材料比对 · 可核对来源';if(a.tool==='ppt')return '演示提纲 · 尚未生成 PPT 文件';return a.kind+' · '+(a.data.stage==='draft'?'可继续编辑':'结构模板');}
function assetTableRow(a){const token=esc(assetToken(a)),p=projectOf(a.projectId);return `<tr><td><div class="asset-name"><span class="hub-row-icon ${a.type==='report'?'teal':''}">${icon(a.type==='report'?'search':a.tool==='ppt'?'chart':assetCategory(a)==='literature'?'book':'file',20)}</span><div><a class="asset-title" href="${esc(a.url)}">${esc(a.title)}</a><small>${esc(assetDescription(a))}</small></div></div></td><td><span class="asset-type ${a.type==='report'?'report':''}">${esc(a.kind)}</span></td><td>${p?`<a class="asset-project" href="#project/${encodeURIComponent(p.id)}">${esc(p.name)}</a>`:'<span class="asset-muted">未归入项目</span>'}</td><td><time class="asset-time">${esc(assetDate(a))}</time></td><td><div class="asset-actions"><a href="${esc(a.url)}">${a.type==='report'?'查看报告':'继续编辑'}</a><button data-asset-export="${token}">导出</button><details class="asset-menu"><summary aria-label="更多操作：${esc(a.title)}">⋯</summary><div><button data-asset-project="${token}">移动到项目</button><button data-asset-info="${token}">查看成果信息</button></div></details></div></td></tr>`;}
function updateAssetTable(){const selected=selectAssets(assets,{category:assetFilter,project:assetProject,query:assetQuery,sort:assetSort},projects());$('#asset-count').textContent=`共 ${selected.length} 份成果`;$('#asset-table-body').innerHTML=selected.map(assetTableRow).join('')||`<tr><td colspan="5"><div class="asset-empty">${icon('file',32)}<h3>${assets.length?'没有匹配的成果':'开始积累你的研究成果'}</h3><p>${assets.length?'尝试调整分类、项目或关键词。':'保存大纲、创作模板或比对报告后，会显示在这里。'}</p>${assets.length?'<button class="btn secondary" data-reset-assets>清除筛选</button>':'<button class="btn primary" data-new-task>新建任务</button>'}</div></td></tr>`;}
function renderAssets(){ $('.dashboard').innerHTML=`${heading('我的成果','找到需要的内容，继续编辑、核对报告或导出交付。','<button class="btn primary" data-new-task>'+icon('plus',16)+' 新建任务</button>')}<section class="card asset-library"><div class="asset-tabs hub-tabs" role="group" aria-label="成果分类">${assetCategories.map(([id,label])=>`<button data-asset-filter="${id}" class="${id===assetFilter?'active':''}" aria-pressed="${id===assetFilter}">${label}<span>${id==='all'?assets.length:assets.filter(a=>assetCategory(a)===id).length}</span></button>`).join('')}</div><div class="asset-toolbar"><label class="asset-search">${icon('search',17)}<input id="asset-query" aria-label="搜索成果或项目名称" value="${esc(assetQuery)}" placeholder="搜索成果或项目名称"></label><select id="asset-project-filter" aria-label="筛选所属项目"><option value="all">所有项目</option><option value="none" ${assetProject==='none'?'selected':''}>未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${assetProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="asset-sort" aria-label="成果排序">${[['updated','最近更新'],['created','最近创建'],['name','名称排序']].map(([v,n])=>`<option value="${v}" ${assetSort===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="asset-table-caption"><span id="asset-count"></span><span>保存的内容与报告，统一管理</span></div><table class="asset-table"><thead><tr><th scope="col">成果名称</th><th scope="col">类型</th><th scope="col">所属项目</th><th scope="col">更新时间</th><th scope="col">操作</th></tr></thead><tbody id="asset-table-body"></tbody></table><div class="asset-footer">同名内容不自动合并，历史记录均保留。</div>${reportError?'<p class="hub-error">查重报告读取失败，请检查当前浏览器存储权限。</p>':''}</section><aside class="asset-backup">${icon('shield',22)}<div><b>本地成果，请及时备份</b><p>内容保存在当前浏览器，更换设备或清理数据可能丢失。</p></div><button class="btn secondary" data-workspace-backup>导出工作空间备份</button></aside>`;updateAssetTable();$('#asset-query').addEventListener('input',e=>{assetQuery=e.target.value;updateAssetTable();});$('#asset-project-filter').addEventListener('change',e=>{assetProject=e.target.value;updateAssetTable();});$('#asset-sort').addEventListener('change',e=>{assetSort=e.target.value;updateAssetTable();});}
function exportAsset(a){if(a.type==='draft'){modal('导出成果',`<p class="hub-intro">${esc(a.title)}</p><p class="hub-description">导出可编辑的纯文本（TXT），不包含排版。${a.tool==='ppt'?'当前成果是演示提纲，不是 PPT 文件。':''}</p><button class="btn primary" data-export-draft="${esc(a.id)}">下载 TXT 文本</button>`);return;}modal('导出查重报告',`<p class="hub-intro">${esc(a.title)}</p><p class="hub-description">HTML 保留正文标记和来源证据；JSON 用于数据备份。需要 PDF 可打开报告后打印保存。</p><div class="hub-project-actions"><button class="btn primary" data-report-download="${esc(a.id)}" data-format="html">下载 HTML 报告</button><button class="btn secondary" data-report-download="${esc(a.id)}" data-format="json">下载 JSON 数据</button><a class="btn secondary" href="${esc(a.url)}">打开报告 / 打印 PDF</a></div>`);}
function renderTasks(){const ts=allTasks();$('.dashboard').innerHTML=heading('任务中心','查看真实本地操作记录；在线排队、取消与失败重试仍待后台接入。')+`<section class="card hub-card">${ts.map(taskRow).join('')||empty('暂无任务记录，保存创作成果或执行本地材料比对后可在此查看。','#category/writing')}<p class="hub-footnote">本地记录不代表 AI 模型调用。已完成的查重任务只覆盖报告中列出的材料。</p></section>`;}
function renderAccount(section){const p=profile(),pref=preferences();$('.dashboard').innerHTML=heading('账户中心','当前只管理本地资料，真实账号和跨设备同步尚未接入。')+`<div class="hub-account-page"><section class="card hub-card"><div class="hub-account-summary">${avatar()}<div><b>${esc(p.name)}</b><p>本地体验空间</p></div>${badge('未连接在线账户','gray')}</div><form id="profile-form" class="hub-form"><label for="profile-name">昵称</label><input id="profile-name" required maxlength="20" value="${esc(p.name)}"><div class="hub-form-row"><div><label for="profile-degree">学段 / 身份</label><select id="profile-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===(p.degree||pref.degree)?'selected':''}>${d}</option>`).join('')}</select></div><div><label for="profile-major">学科专业</label><input id="profile-major" maxlength="100" value="${esc(p.major||'')}"></div></div><label for="profile-direction">研究方向（可选）</label><textarea id="profile-direction" rows="3" maxlength="500">${esc(p.direction||'')}</textarea><button class="btn primary" type="submit">保存个人资料</button></form></section><section class="card hub-card" id="account-security"><h2>登录与安全</h2><p class="hub-description">本地昵称不是正式账号。当前无需真实手机、邮箱或密码，也没有在线登录会话。</p><div class="hub-status-lines"><div>手机号 / 邮箱绑定 ${badge('待接入','gray')}</div><div>密码与登录设备 ${badge('待接入','gray')}</div><div>云端数据同步 ${badge('待接入','gray')}</div></div><a class="btn secondary" href="#settings/privacy">查看数据保存说明</a></section></div>`;$('#profile-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#profile-name').value.trim();if(!name){notify('请填写昵称。');return;}guard(()=>{write(keys.profile,{...profile(),name,degree:$('#profile-degree').value,major:$('#profile-major').value.trim(),direction:$('#profile-direction').value.trim()});updateProfile();notify('本地个人资料已保存。');});});if(section==='security')$('#account-security').scrollIntoView({block:'start'});}
function updateProfile(){document.querySelectorAll('.hub-profile-name').forEach(n=>n.textContent=profile().name);document.querySelectorAll('.hub-avatar').forEach(n=>n.textContent=Array.from(profile().name||'研究者')[0]);}
function renderSettings(section){const p=preferences();$('.dashboard').innerHTML=heading('设置中心','这些设置保存在当前浏览器，并应用于新建项目与论文任务。')+`<div class="hub-account-page"><section class="card hub-card"><h2>写作与界面偏好</h2><form id="settings-form" class="hub-form"><div class="hub-form-row"><div><label for="default-degree">默认学段</label><select id="default-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===p.degree?'selected':''}>${d}</option>`).join('')}</select></div><div><label for="default-major">默认学科专业</label><input id="default-major" maxlength="100" value="${esc(p.major)}" placeholder="例如：教育学"></div></div><div class="hub-form-row"><div><label for="setting-density">列表显示密度</label><select id="setting-density"><option value="comfortable" ${p.density==='comfortable'?'selected':''}>舒适</option><option value="compact" ${p.density==='compact'?'selected':''}>紧凑</option></select></div><div><label for="setting-font">界面字号</label><select id="setting-font"><option value="normal" ${p.fontSize==='normal'?'selected':''}>标准</option><option value="large" ${p.fontSize==='large'?'selected':''}>较大</option></select></div></div><button class="btn primary" type="submit">保存设置</button><p class="hub-footnote">默认学段和专业只用于新建内容，不覆盖已有草稿。</p></form></section><section class="card hub-card" id="privacy-settings"><h2>数据与隐私</h2><div class="hub-status-lines"><div>项目与创作草稿 <b>当前浏览器保存</b></div><div>查重报告与对照正文 <b>当前浏览器 IndexedDB</b></div><div>论文文件处理 <b>本地解析，不自动上传</b></div><div>云端同步 ${badge('未接入','gray')}</div></div><p class="hub-description">清理浏览器数据或更换设备可能无法找回本地内容。请及时导出备份；此页面不改变查重数据源范围。</p><button class="btn secondary" id="backup-button">导出当前工作空间备份</button><p class="hub-footnote">备份包含项目、个人资料、设置、草稿、任务和报告正文，请自行妥善保存。导出不代表云端同步。</p></section></div>`;$('#settings-form').addEventListener('submit',e=>{e.preventDefault();guard(()=>{write(keys.preferences,{...preferences(),degree:$('#default-degree').value,major:$('#default-major').value.trim(),density:$('#setting-density').value,fontSize:$('#setting-font').value});applyPreferences();notify('设置已保存，默认值将用于新建任务。');});});$('#backup-button').addEventListener('click',exportWorkspace);if(section==='privacy')$('#privacy-settings').scrollIntoView({block:'start'});}
function renderMembership(){ $('.dashboard').innerHTML=heading('会员与用量','当前为本地体验，无已生效的付费会员、余额或在线额度。')+`<div class="hub-account-page"><section class="card hub-card"><h2>当前可用范围</h2>${badge('本地体验','blue')}<ul class="hub-feature-list"><li>大纲与结构模板、编辑及保存</li><li>Word / PDF / TXT 本地解析</li><li>本地材料比对与来源核对</li><li>输入数据绘图与成果导出</li><li>项目、成果与本地资料管理</li></ul><a class="btn primary" href="#category/writing">开始写作</a></section><section class="card hub-card"><h2>AI 与在线服务</h2>${badge('尚未接入','gray')}<p class="hub-description">模型、在线数据库、正式账号与支付接入后，会公布套餐、计量方式、权益期限和费用处理规则。当前不会扣款，也不展示虚构用量。</p><div class="hub-status-lines"><div>付费会员 <b>未开放</b></div><div>在线使用额度 <b>暂无</b></div><div>订单与支付 <a href="#orders">查看状态 →</a></div></div></section></div>`;}
function renderOrders(){ $('.dashboard').innerHTML=heading('订单记录','正式支付与订单服务尚未接入。')+`<section class="card hub-card">${empty('暂无订单，当前本地体验不会产生扣款。','#membership','查看会员与用量')}<p class="hub-footnote">不生成模拟支付成功记录；正式服务上线后显示真实订单与支付状态。</p></section>`;}
function renderHelp(){ $('.dashboard').innerHTML=heading('帮助与反馈','了解实际可用范围，记录需要改进的问题。')+`<div class="hub-account-page"><section class="card hub-card"><h2>使用帮助</h2><div class="hub-help-links"><a href="/precheck/#/help">论文查重与文档解析 →</a><a href="#settings/privacy">本地保存与备份 →</a><a href="#membership">功能开放状态 →</a><a href="/">返回官网 →</a></div><p class="hub-description">扫描 PDF 暂不支持 OCR；在线 AI、查重检索、账号与支付仍待接入。降 AI 率不保证检测分数下降或通过。</p></section><section class="card hub-card"><h2>记录反馈</h2><form id="hub-feedback-form" class="hub-form"><label for="feedback-content">遇到的问题或建议</label><textarea id="feedback-content" required rows="6" maxlength="3000" placeholder="说明操作步骤、页面和希望改进的内容…"></textarea><button class="btn primary" type="submit">导出反馈文本</button><p class="hub-footnote">只导出到本地，不会自动发送给任何人。</p></form></section></div>`;$('#hub-feedback-form').addEventListener('submit',e=>{e.preventDefault();const text=$('#feedback-content').value.trim();if(!text){notify('请填写反馈内容。');return;}download('PaperKnow-反馈.txt',text);notify('已发起反馈文本下载。');});}
function renderCategory(key){const c=categories.find(c=>c[0]===key);if(!c){overview();return;}if(key==='writing'){mountTool('writing');return;}$('.dashboard').innerHTML=heading(c[1],'选择具体任务，进入对应的操作页面。')+`<div class="hub-tool-grid">${c[3].map(id=>{const name=id==='check'?'论文查重':toolConfigs[id][0],desc=id==='check'?'解析正文，与本地对照材料执行文本比对。':toolConfigs[id][1],status=id==='check'?'本地材料比对':id==='research'?'本地绘图':id==='aigc'?'检测未接入':'结构或流程模板';return `<a class="hub-tool-card" href="${id==='check'?'/precheck/':'#tool/'+id}"><span class="hub-row-icon">${icon(id==='check'?'search':c[2],25)}</span>${badge(status,'gray')}<h2>${name}</h2><p>${desc}</p><span>开始使用 ${icon('arrow',14)}</span></a>`;}).join('')}</div><p class="hub-footnote">AI、在线检索与正式检测服务尚未接入，当前能力以各页面说明为准。</p>`;}
function renderSearch(q){$('.dashboard').innerHTML=heading('搜索结果',`搜索“${esc(q)}”，范围为项目标题、成果标题和工具名称。`)+`<section class="card hub-card"><h2>项目</h2>${projects().filter(p=>p.name.includes(q)).map(projectRow).join('')||empty('没有匹配的项目。')}</section><section class="card hub-card"><h2>成果</h2>${assets.filter(a=>a.title.includes(q)||a.kind.includes(q)).map(assetRow).join('')||empty('没有匹配的成果。')}</section><section class="card hub-card"><h2>工具</h2>${Object.entries(toolConfigs).filter(([,c])=>(c[0]+c[1]).includes(q)).map(([id,c])=>`<a class="hub-search-result" href="#tool/${id}">${icon('file')}<span>${esc(c[0])}</span>${icon('arrow',14)}</a>`).join('')||empty('没有匹配的工具。')}</section>`;}
function routeInfo(){const hash=location.hash.slice(1)||'home',at=hash.indexOf('?'),path=at>=0?hash.slice(0,at):hash,params=new URLSearchParams(at>=0?hash.slice(at+1):'');return {parts:path.split('/'),params};}
function render(){refreshAssets();$('.dashboard').className='page dashboard hub-page';$('.sidebar').classList.remove('mobile-open');$('#account-menu').hidden=true;const {parts,params}=routeInfo(),route=parts[0],id=parts[1];let active='#'+route,title={home:'工作台 / 概览',projects:'我的项目',project:'我的项目',assets:'我的成果',recent:'我的成果',tasks:'任务中心',account:'账户中心',settings:'设置中心',membership:'会员与用量',orders:'订单记录',help:'帮助与反馈',search:'搜索'}[route]||'研究工作台';
if(route==='category'){const key=legacy[id]||id;active='#category/'+key;title=categories.find(c=>c[0]===key)?.[1]||title;renderCategory(key);}else if(route==='tool'){const parent=categories.find(c=>c[3].includes(id));active='#category/'+(parent?.[0]||'writing');if(!mountTool(id,undefined,params.get('project'))){overview();notify('没有找到对应工具。');}title=toolConfigs[id]?.[0]||title;}else if(route==='draft'){const d=list(keys.drafts).find(d=>String(d.id)===id);active='#category/'+(categories.find(c=>c[3].includes(d?.tool||'writing'))?.[0]||'writing');if(d)mountTool(d.tool||'writing',d.id);else{$('.dashboard').innerHTML=empty('当前浏览器中没有此成果。','#assets','查看成果');}title=d?.title||'成果不存在';}else if(route==='projects')renderProjects();else if(route==='project'){active='#projects';projectDetail(id);}else if(route==='assets'||route==='recent'){active='#assets';renderAssets();}else if(route==='tasks')renderTasks();else if(route==='account')renderAccount(id);else if(route==='settings')renderSettings(id);else if(route==='membership')renderMembership();else if(route==='orders')renderOrders();else if(route==='help')renderHelp();else if(route==='search'){let q='';try{q=decodeURIComponent(id||'');}catch{}renderSearch(q);}else{active='#home';overview();}$('.breadcrumb strong').textContent=title;document.querySelectorAll('.sidebar .nav-link').forEach(a=>{const selected=a.getAttribute('href')===active;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(!['privacy','security'].includes(id))window.scrollTo({top:0});}
document.addEventListener('click',async e=>{const menu=e.target.closest('[data-account-menu]');if(menu){$('#account-menu').hidden=!$('#account-menu').hidden;return;}if(!e.target.closest('#account-menu'))$('#account-menu').hidden=true;if(e.target.closest('[data-reset-assets]')){assetFilter='all';assetProject='all';assetQuery='';renderAssets();return;}const ex=e.target.closest('[data-asset-export]');if(ex){const a=assetByToken(ex.dataset.assetExport);if(a)exportAsset(a);return;}const rd=e.target.closest('[data-report-download]');if(rd){const r=reports.find(r=>r.id===rd.dataset.reportDownload);if(!r)return;const html=rd.dataset.format==='html';download((r.title||'论文')+'-PaperKnow报告.'+(html?'html':'json'),html?reportHtml(r):JSON.stringify(r,null,2),html?'text/html':'application/json');notify('已发起报告下载。');return;}const info=e.target.closest('[data-asset-info]');if(info){const a=assetByToken(info.dataset.assetInfo);if(a)modal('成果信息',`<div class="hub-status-lines"><div>名称 <b>${esc(a.title)}</b></div><div>类型 <b>${esc(a.kind)}</b></div><div>所属项目 <b>${esc(projectOf(a.projectId)?.name||'未归入项目')}</b></div><div>更新时间 <b>${esc(assetDate(a))}</b></div></div><p class="hub-description">${esc(assetDescription(a))}</p><p class="hub-footnote">记录编号：${esc(a.id)}。内容保存在当前浏览器。</p>`);return;}const backup=e.target.closest('[data-workspace-backup]');if(backup){exportWorkspace();return;}const stage=e.target.closest('[data-stage-project]');if(stage){stageForm(stage.dataset.stageProject);return;}const view=e.target.closest('[data-project-view]');if(view){projectView=view.dataset.projectView;guard(()=>write(keys.preferences,{...preferences(),projectView}));renderProjects();return;}if(e.target.closest('[data-reset-projects]')){projectQuery='';activeProjectFilter='all';renderProjects();return;}const newTaskButton=e.target.closest('[data-new-task]');if(newTaskButton){newTask();return;}const uploadButton=e.target.closest('[data-upload-task]');if(uploadButton){uploadTask();return;}const homeFilter=e.target.closest('[data-home-filter]');if(homeFilter){homeAssetFilter=homeFilter.dataset.homeFilter;$('#home-results').innerHTML=homeResults();return;}if(e.target.closest('#workspace-dialog a[href]'))$('#'+dialogId).close();const newP=e.target.closest('[data-new-project]');if(newP){projectForm();return;}const edit=e.target.closest('[data-edit-project]');if(edit){projectForm(edit.dataset.editProject);return;}const archive=e.target.closest('[data-archive-project]');if(archive){guard(()=>{const id=archive.dataset.archiveProject;write(keys.projects,projects().map(p=>p.id===id?{...p,status:p.status==='archived'?'active':'archived',updatedAt:new Date().toISOString()}:p));render();notify('项目状态已更新，成果仍保留。');});return;}const link=e.target.closest('[data-link-project]');if(link){linkProject(link.dataset.linkProject);return;}const pf=e.target.closest('[data-project-filter]');if(pf){activeProjectFilter=pf.dataset.projectFilter;renderProjects();return;}const af=e.target.closest('[data-asset-filter]');if(af){assetFilter=af.dataset.assetFilter;renderAssets();return;}const binding=e.target.closest('[data-bind-asset]');if(binding){const token=binding.dataset.bindAsset,index=token.indexOf(':');await bindAsset(token.slice(0,index),token.slice(index+1),binding.dataset.targetProject);return;}const manage=e.target.closest('[data-asset-project]');if(manage){const token=manage.dataset.assetProject,i=token.indexOf(':'),a=assets.find(a=>a.type===token.slice(0,i)&&a.id===token.slice(i+1));modal('管理项目关联',`<form class="hub-form" id="asset-binding-form"><label for="asset-project-select">所属项目</label><select id="asset-project-select"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${a?.projectId===p.id?'selected':''}>${esc(p.name)}${p.status==='archived'?'（已归档）':''}</option>`).join('')}</select><button class="btn primary" type="submit">保存关联</button></form>`);$('#asset-binding-form').addEventListener('submit',async ev=>{ev.preventDefault();const projectId=$('#asset-project-select').value;$('#'+dialogId).close();await bindAsset(token.slice(0,i),token.slice(i+1),projectId);});return;}const exportD=e.target.closest('[data-export-draft]');if(exportD){const d=list(keys.drafts).find(d=>String(d.id)===exportD.dataset.exportDraft);if(!d)return;let text=d.text||'';if(!text&&d.html){const div=document.createElement('div');div.innerHTML=d.html;div.querySelectorAll('p,h3,h4').forEach(n=>n.append(document.createTextNode('\n')));text=div.textContent||'';}if(!text.trim()){notify('这份成果尚无正文，请先继续编辑并保存内容。');return;}download((d.title||'论文成果')+'.txt',text);$('#'+dialogId).close();notify('已发起文本下载。');}});
window.addEventListener('hashchange',render);window.addEventListener('storage',()=>{updateProfile();applyPreferences();render();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#account-menu').hidden=true;$('.sidebar').classList.remove('mobile-open');}});
shell();try{reports=(await repository.all('reports')).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));}catch{reportError=true;}render();
